"""Vision tool for analyzing images using Claude's multimodal capabilities."""

import os
import base64
from claude_agent_sdk import tool
from typing import Any


@tool(
    "analyze_image",
    "Analyze an image file using Claude's vision capabilities. Describe what's in the image, read text/numbers, interpret charts/diagrams. Provide a specific question about what to look for.",
    {"file_path": str, "question": str},
)
async def analyze_image(args: dict[str, Any]) -> dict[str, Any]:
    file_path = args["file_path"]
    question = args.get("question", "Describe this image in detail. If there is text, transcribe it exactly.")

    if not os.path.exists(file_path):
        return {"content": [{"type": "text", "text": f"Image not found: {file_path}"}]}

    try:
        import anthropic

        # Read and encode image
        with open(file_path, "rb") as f:
            image_data = base64.standard_b64encode(f.read()).decode("utf-8")

        ext = os.path.splitext(file_path)[1].lower()
        media_type_map = {
            ".png": "image/png",
            ".jpg": "image/jpeg",
            ".jpeg": "image/jpeg",
            ".gif": "image/gif",
            ".webp": "image/webp",
            ".bmp": "image/bmp",
        }
        media_type = media_type_map.get(ext, "image/png")

        client = anthropic.Anthropic()
        message = client.messages.create(
            model="claude-sonnet-4-6",
            max_tokens=2000,
            messages=[
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "image",
                            "source": {
                                "type": "base64",
                                "media_type": media_type,
                                "data": image_data,
                            },
                        },
                        {
                            "type": "text",
                            "text": question,
                        },
                    ],
                }
            ],
        )

        response_text = message.content[0].text
        return {"content": [{"type": "text", "text": f"Image analysis of {file_path}:\n\n{response_text}"}]}

    except ImportError:
        return {"content": [{"type": "text", "text": "anthropic package not available for vision analysis"}]}
    except Exception as e:
        return {"content": [{"type": "text", "text": f"Vision analysis error: {str(e)}"}]}

"""Wikipedia lookup tool for factual questions."""

import aiohttp
from claude_agent_sdk import tool
from typing import Any


@tool(
    "wikipedia_lookup",
    "Look up a Wikipedia article by title. Returns the article summary and key sections. Use this for factual questions about people, places, events, concepts.",
    {"title": str, "sentences": int},
)
async def wikipedia_lookup(args: dict[str, Any]) -> dict[str, Any]:
    title = args["title"]
    sentences = args.get("sentences", 10)

    try:
        # Use Wikipedia API for structured data
        url = "https://en.wikipedia.org/api/rest_v1/page/summary/" + title.replace(" ", "_")
        async with aiohttp.ClientSession() as session:
            async with session.get(url, timeout=aiohttp.ClientTimeout(total=10)) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    extract = data.get("extract", "")
                    title_found = data.get("title", title)

                    # Also get more detailed content
                    detail_url = f"https://en.wikipedia.org/w/api.php?action=query&titles={title.replace(' ', '_')}&prop=extracts&exintro=false&explaintext=true&exsectionformat=plain&format=json"
                    async with session.get(detail_url, timeout=aiohttp.ClientTimeout(total=10)) as detail_resp:
                        if detail_resp.status == 200:
                            detail_data = await detail_resp.json()
                            pages = detail_data.get("query", {}).get("pages", {})
                            for page_id, page in pages.items():
                                full_extract = page.get("extract", "")
                                if full_extract and len(full_extract) > len(extract):
                                    extract = full_extract

                    if len(extract) > 10000:
                        extract = extract[:10000] + "\n... [truncated]"

                    return {"content": [{"type": "text", "text": f"Wikipedia: {title_found}\n\n{extract}"}]}

                elif resp.status == 404:
                    # Try search
                    search_url = f"https://en.wikipedia.org/w/api.php?action=opensearch&search={title}&limit=5&format=json"
                    async with session.get(search_url, timeout=aiohttp.ClientTimeout(total=10)) as search_resp:
                        if search_resp.status == 200:
                            search_data = await search_resp.json()
                            if len(search_data) > 1 and search_data[1]:
                                suggestions = ", ".join(search_data[1][:5])
                                return {"content": [{"type": "text", "text": f"Article '{title}' not found. Similar articles: {suggestions}"}]}
                    return {"content": [{"type": "text", "text": f"Wikipedia article not found: {title}"}]}

    except Exception as e:
        return {"content": [{"type": "text", "text": f"Wikipedia error: {str(e)}"}]}


@tool(
    "wikipedia_search",
    "Search Wikipedia for articles matching a query. Returns article titles and snippets.",
    {"query": str, "num_results": int},
)
async def wikipedia_search(args: dict[str, Any]) -> dict[str, Any]:
    query_str = args["query"]
    num_results = args.get("num_results", 5)

    try:
        url = f"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={query_str}&srlimit={num_results}&format=json"
        async with aiohttp.ClientSession() as session:
            async with session.get(url, timeout=aiohttp.ClientTimeout(total=10)) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    results = data.get("query", {}).get("search", [])

                    if not results:
                        return {"content": [{"type": "text", "text": f"No Wikipedia results for: {query_str}"}]}

                    text = f"Wikipedia search results for '{query_str}':\n\n"
                    for i, r in enumerate(results, 1):
                        import re
                        snippet = re.sub(r'<[^>]+>', '', r.get("snippet", ""))
                        text += f"{i}. {r['title']}\n   {snippet}\n\n"

                    return {"content": [{"type": "text", "text": text}]}

    except Exception as e:
        return {"content": [{"type": "text", "text": f"Wikipedia search error: {str(e)}"}]}

"""Mathematical computation tools."""

from claude_agent_sdk import tool
from typing import Any


@tool(
    "calculate",
    "Evaluate a mathematical expression or perform calculations. Supports Python math expressions including math module functions.",
    {"expression": str},
)
async def calculate(args: dict[str, Any]) -> dict[str, Any]:
    expression = args["expression"]

    try:
        import math
        import statistics

        # Safe evaluation with math functions available
        allowed_names = {
            k: v for k, v in math.__dict__.items() if not k.startswith("_")
        }
        allowed_names.update({
            "abs": abs, "round": round, "min": min, "max": max,
            "sum": sum, "len": len, "sorted": sorted,
            "int": int, "float": float, "str": str,
            "range": range, "list": list, "tuple": tuple,
            "mean": statistics.mean, "median": statistics.median,
            "stdev": statistics.stdev,
        })

        result = eval(expression, {"__builtins__": {}}, allowed_names)
        return {"content": [{"type": "text", "text": f"Result: {result}"}]}

    except Exception as e:
        return {"content": [{"type": "text", "text": f"Calculation error: {str(e)}\nExpression: {expression}"}]}

"""File download tool for fetching remote resources."""

import os
import aiohttp
from claude_agent_sdk import tool
from typing import Any


@tool(
    "download_file",
    "Download a file from a URL and save it locally. Returns the local file path. Useful for downloading attachments, datasets, images, audio files.",
    {"url": str, "save_as": str},
)
async def download_file(args: dict[str, Any]) -> dict[str, Any]:
    url = args["url"]
    save_as = args.get("save_as", "")

    if not save_as:
        # Generate filename from URL
        from urllib.parse import urlparse
        parsed = urlparse(url)
        save_as = os.path.join("/tmp", os.path.basename(parsed.path) or "downloaded_file")

    try:
        headers = {
            "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36"
        }
        async with aiohttp.ClientSession() as session:
            async with session.get(url, headers=headers, timeout=aiohttp.ClientTimeout(total=60)) as resp:
                if resp.status != 200:
                    return {"content": [{"type": "text", "text": f"Download failed: HTTP {resp.status}"}]}

                content = await resp.read()
                os.makedirs(os.path.dirname(save_as) or ".", exist_ok=True)
                with open(save_as, "wb") as f:
                    f.write(content)

                size = len(content)
                return {"content": [{"type": "text", "text": f"Downloaded {size} bytes to {save_as}"}]}

    except Exception as e:
        return {"content": [{"type": "text", "text": f"Download error: {str(e)}"}]}

